mapper.select:
SELECT cr.id AS reportId, cr.customer_id AS customerId, cr.conversion_status_code AS conversionStatusCode, CASE WHEN cr.conversion_status_code = '01' THEN pc.name WHEN cr.conversion_status_code = '02' THEN ic.name END AS customerName, cr.report_url AS reportUrl, cr.send_status_code AS sendStatusCode FROM customer_report cr LEFT JOIN potential_customer pc ON cr.conversion_status_code = '01' AND pc.id = cr.customer_id LEFT JOIN integrated_customer ic ON cr.conversion_status_code = '02' AND ic.integrated_customer_id = cr.customer_id WHERE cr.customer_id = #{customerId}
AND cr.conversion_status_code = #{conversionStatusCode}
AND ( (cr.conversion_status_code = '01' AND pc.sales_user_id = #{currentUserId} AND pc.is_active = FALSE) OR ( cr.conversion_status_code = '02' AND ic.sales_user_id = #{currentUserId} AND ic.birth_date > DATE_SUB(CURDATE(), INTERVAL 21 YEAR) AND EXISTS ( SELECT 1 FROM webform_response wr WHERE wr.customer_id = cr.customer_id AND wr.conversion_status_code = '02' ) ) ) ORDER BY cr.created_at DESC, cr.id DESC LIMIT 1

mapper.update:
UPDATE customer_report
SET send_status_code = '02',
    sent_at = #{sentAt}
WHERE id = #{reportId}
  AND send_status_code IN ('01', '02', '03')
